(() => {
  const themes=['light','paper','night'],labels={light:'日间',paper:'纸张',night:'夜间'},key='kaoyan-study-theme';
  let current='light';
  try{const saved=localStorage.getItem(key);if(themes.includes(saved))current=saved;}catch{}
  const apply=value=>{current=value;document.documentElement.dataset.theme=value;const button=document.getElementById('theme-toggle');if(button){button.textContent='主题：'+labels[value];button.setAttribute('aria-label','当前'+labels[value]+'主题，点击切换');}};
  apply(current);
  document.addEventListener('DOMContentLoaded',()=>{const header=document.querySelector('header');if(header){const button=document.createElement('button');button.id='theme-toggle';button.className='theme-toggle';button.type='button';button.onclick=()=>{const next=themes[(themes.indexOf(current)+1)%themes.length];try{localStorage.setItem(key,next);}catch{}apply(next);};header.append(button);apply(current);}const brand=document.querySelector('#sidebar .brand');if(brand)brand.href='index.html';const top=document.createElement('button');top.id='back-to-top';top.className='back-to-top';top.type='button';top.setAttribute('aria-label','回到顶部');top.textContent='↑ 顶部';document.body.append(top);const sync=()=>top.classList.toggle('is-visible',window.scrollY>420);top.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));window.addEventListener('scroll',sync,{passive:true});sync();const style=document.createElement('style');style.textContent='.back-to-top{position:fixed;right:22px;bottom:22px;z-index:20;border:1px solid var(--line);border-radius:999px;padding:9px 14px;background:#fff;color:var(--blue);box-shadow:0 8px 24px #1c2b4820;font-size:13px;font-weight:650;opacity:0;transform:translateY(10px);pointer-events:none;transition:opacity .2s,transform .2s}.back-to-top.is-visible{opacity:1;transform:none;pointer-events:auto}.back-to-top:hover{border-color:var(--blue);background:#eef2ff}.question-picker{position:sticky;top:0;z-index:6;background:#f5f7fb;padding:8px 0 6px;box-shadow:0 10px 12px #f5f7fb}.question-picker .picker-label{font-size:12px;color:var(--muted);font-weight:650;margin:0 0 5px}.question-picker .exam-grid{margin:4px 0}.question-picker .exam-grid a{min-width:32px}.question-picker .exam-grid a[aria-current=true]{background:var(--blue);border-color:var(--blue);color:#fff}.qbody{max-width:100%;overflow-x:auto;overflow-wrap:anywhere}.qbody .katex-display{overflow-x:auto;overflow-y:hidden;padding:4px 0}.qbody .katex{white-space:normal}.qbody img{display:block;margin:10px auto;max-width:100%;height:auto}.qbody sub,.qbody sup{line-height:0}@media(max-width:720px){.back-to-top{right:14px;bottom:14px;padding:8px 11px}.question-picker{margin-left:-18px;margin-right:-18px;padding:7px 18px}.question-picker .exam-grid{grid-template-columns:repeat(8,1fr);gap:6px}.question-picker .exam-grid a{padding:5px 2px}.qbody .katex-display{font-size:.94em}}@media(prefers-color-scheme:dark){.back-to-top{background:#222e40}}';document.head.append(style);});
})();
